use super::*;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use super::tests::cleanup;
fn complete(poll:crate::RetainedWorkPoll)->RetainedWorkOutcome{super::tests::complete(poll)}
fn settle(bank:&mut EffectBank,grant:RetainedCloneGrant,turn:RetainedWorkOutcome,marker:Option<usize>,heap:(usize,usize))->RetainedWorkOutcome{let progress=turn.result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());cleanup::post(bank,grant,turn.work,progress,marker,heap);turn}
#[test]fn actual_typed_storage_caller_slots_preserve_bodies_without_constructor_or_destructor_callbacks(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../../📐️.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&f["stock"]));let original=f["moveText"].as_str().unwrap().to_owned();let pointer=original.as_ptr();let mut input=Some(original);let mut owner=NativeOwnedStorage::<String>::empty();
 let g=bank.loan(1,usize::MAX);let(((poll,marker,heap),attempts))=semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||cleanup::run(&mut bank,g,1,|effect|owner.reserve_empty(effect)));assert_eq!(attempts,1);let turn=settle(&mut bank,g,complete(poll),marker,heap);assert_eq!(turn.work,1);let error=turn.result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::AllocationFailed);assert_eq!(f["nullKind"],"AllocationFailed");assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(!owner.reserved());
 let g=bank.loan(1,usize::MAX);let(poll,marker,heap)=cleanup::run(&mut bank,g,1,|effect|owner.reserve_empty(effect));let turn=settle(&mut bank,g,complete(poll),marker,heap);turn.result.unwrap();let address=owner.address();
 let g=RetainedCloneGrant{maximum_items:0,..bank.loan(1,usize::MAX)};let(poll,marker,heap)=cleanup::run(&mut bank,g,1,|effect|crate::RetainedWorkPoll::Complete(owner.put_from(&mut input,effect)));let turn=settle(&mut bank,g,complete(poll),marker,heap);assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(!owner.initialized());
 let g=bank.loan(1,usize::MAX);let(poll,marker,heap)=cleanup::run(&mut bank,g,1,|effect|crate::RetainedWorkPoll::Complete(owner.put_from(&mut input,effect)));let turn=settle(&mut bank,g,complete(poll),marker,heap);assert_eq!(turn.work,1);assert_eq!(turn.result.unwrap().progress().copied_bytes,NativeOwnedStorage::<String>::move_demand().copy_bytes);assert!(input.is_none());assert_eq!(owner.get().unwrap().as_ptr(),pointer);assert_eq!(owner.address(),address);
 let g=bank.loan(1,usize::MAX);let(poll,marker,heap)=cleanup::run(&mut bank,g,1,|effect|crate::RetainedWorkPoll::Complete(owner.release(effect)));let turn=settle(&mut bank,g,complete(poll),marker,heap);assert_eq!(turn.work,u128::from(f["liveReleaseWork"].as_u64().unwrap()));assert!(turn.result.is_err());assert_eq!(heap,(0,0));assert_eq!(owner.get().unwrap().as_ptr(),pointer);
 let mut output=Some(String::from("occupied"));let g=bank.loan(1,usize::MAX);let(poll,marker,heap)=cleanup::run(&mut bank,g,1,|effect|crate::RetainedWorkPoll::Complete(owner.take_into(&mut output,effect)));let turn=settle(&mut bank,g,complete(poll),marker,heap);assert_eq!(turn.work,u128::from(f["occupiedOutputWork"].as_u64().unwrap()));assert!(turn.result.is_err());assert_eq!(heap,(0,0));assert_eq!(output.as_deref(),Some("occupied"));cleanup::close(output.take().unwrap(),&mut bank,10000);
 let g=bank.loan(1,usize::MAX);let(poll,marker,heap)=cleanup::run(&mut bank,g,1,|effect|crate::RetainedWorkPoll::Complete(owner.take_into(&mut output,effect)));let turn=settle(&mut bank,g,complete(poll),marker,heap);assert_eq!(turn.work,1);assert_eq!(turn.result.unwrap().progress().copied_bytes,NativeOwnedStorage::<String>::move_demand().copy_bytes);assert!(!owner.initialized());assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),f["moveText"]);
 let g=bank.loan(1,usize::MAX);let(poll,marker,heap)=cleanup::run(&mut bank,g,1,|effect|crate::RetainedWorkPoll::Complete(owner.release(effect)));let turn=settle(&mut bank,g,complete(poll),marker,heap);turn.result.unwrap();assert!(owner.terminal_is_empty());cleanup::close(output.take().unwrap(),&mut bank,10000);let g=RetainedCloneGrant::default();let(poll,marker,heap)=cleanup::run(&mut bank,g,0,|effect|crate::RetainedWorkPoll::Complete(owner.release(effect)));let turn=settle(&mut bank,g,complete(poll),marker,heap);assert_eq!(turn.work,0);assert_eq!(semio_framework_value_testing_allocator::observe_retirement_allocations(||drop(owner)).1,(0,0));assert!(bank.is_idle());
}
